async fn handle_connection(mut socket: TcpStream) -> std::io::Result<()> {
    let mut buffer = [0u8; 8192];
    let read = socket.read(&mut buffer).await?;
    if read == 0 {
        return Ok(());
    }
    let request = String::from_utf8_lossy(&buffer[..read]);
    let mut parts = request
        .lines()
        .next()
        .unwrap_or_default()
        .split_whitespace();
    let method = parts.next().unwrap_or("GET");
    let raw_path = parts.next().unwrap_or("/");
    let path = raw_path.split('?').next().unwrap_or("/");
    let (status, body, content_type) = route_request(method, path);
    let body_bytes = body.as_bytes();
    let response = format!(
        "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body_bytes.len(),
        body
    );
    socket.write_all(response.as_bytes()).await?;
    Ok(())
}

fn route_request(method: &str, path: &str) -> (&'static str, String, &'static str) {
    if method != "GET" {
        return (
            "405 Method Not Allowed",
            "method not allowed".to_string(),
            "text/plain",
        );
    }

    if path == "/" || path == "/bench/start" {
        return (
            "200 OK",
            "<!doctype html><html><head><title>mbus bench start</title></head><body><h1>MBUS BENCH START</h1></body></html>".to_string(),
            "text/html; charset=utf-8",
        );
    }

    if let Some(suffix) = path.strip_prefix("/bench/task-") {
        let id = suffix
            .chars()
            .take_while(|ch| ch.is_ascii_digit())
            .collect::<String>();
        if id.len() == 2 {
            let marker = format!("BENCH TASK {id}");
            let body = format!(
                "<!doctype html><html><head><title>{marker}</title></head><body><h1>{marker}</h1><p>{marker} READY</p></body></html>"
            );
            return ("200 OK", body, "text/html; charset=utf-8");
        }
    }

    (
        "404 Not Found",
        "not found".to_string(),
        "text/plain; charset=utf-8",
    )
}

